using System;
using System.Collections.Generic;
using System.Globalization;
using System.Reflection;
using UnityEngine;

// Scene-free integration checks: no map, physics, navigation or checkpoint files.
public static class ChoiceEffectsRuntimeChecks {
 static int checks;
 static void Check(bool value,string label){checks++;if(!value)throw new Exception("CHOICE_EFFECTS_RUNTIME: "+label);}
 static void Reject(Action run,string label){bool threw=false;try{run();}catch(ArgumentException){threw=true;}Check(threw,label);}
 static void Near(double actual,double expected,string label){Check(Math.Abs(actual-expected)<.000001,label+" actual="+actual+" expected="+expected);}
 static void Clock(EconomyLedger ledger,double seconds){typeof(EconomyLedger).GetProperty("Elapsed").SetValue(ledger,seconds,null);}
 static void Set(Dictionary<string,object> profile,string id,double value){foreach(object o in ContentJson.Array(profile["values"])){var row=ContentJson.Object(o);if((string)row["id"]==id){row["value"]=value.ToString(CultureInfo.InvariantCulture);return;}}throw new Exception("Missing fixture setting "+id);}
 static void FixtureProfile(){
  var profile=ContentJson.Object(ContentJson.Parse(ContentTuning.CaptureJson()));
  foreach(object o in ContentJson.Array(profile["values"])){var row=ContentJson.Object(o);if(((string)row["id"]).StartsWith("choice.",StringComparison.Ordinal))row["value"]="0";}
  Set(profile,"choice.effects.version",1);
  string p="choice.request.Empathy.Accept.";
  Set(profile,p+"immediate.satisfaction",3);Set(profile,p+"immediate.fatigue",2);
  Set(profile,p+"during.satisfactionPerMinute",6);Set(profile,p+"during.fatiguePerMinute",1);Set(profile,p+"during.fatigueGrowthPercent",100);
  Set(profile,p+"end.success.satisfaction",7);Set(profile,p+"end.success.fatigue",3);
  Set(profile,"choice.type.Food.1.immediate.satisfaction",9);Set(profile,"choice.type.SleepingFollowup.0.immediate.satisfaction",4);Set(profile,"choice.situation.Jolt.0.immediate.fatigue",-2);
  profile["contentHash"]=ContentTuning.ComputeHash(profile);ContentTuning.UseJson(ContentJson.Stringify(profile));
 }
 public static void Run(){
  checks=0;string original=ContentTuning.CaptureJson();bool hadProfile=ContentJson.Array(ContentJson.Object(ContentJson.Parse(original))["values"]).Count>0;var catalog=Resources.Load<TextAsset>("Content/catalog");Check(catalog!=null,"catalog resource exists");ContentTuning.ConfigureCatalog(catalog.text);
  if(!hadProfile)original=ContentTuning.CaptureJson();float originalScale=Time.timeScale;GameObject root=null;
  try{
   FixtureProfile();Time.timeScale=1;
   foreach(var viewport in new[]{new Vector3(1280,720,1),new Vector3(1920,1080,1),new Vector3(1280,720,1.5f),new Vector3(1920,1080,2)}){
    Rect panel=PassengerDialogueUI.PanelBounds(viewport.x,viewport.y,viewport.z,12000);
    Check(panel.xMin>=0&&panel.yMin>=0&&panel.xMax<=viewport.x/viewport.z&&panel.yMax<=viewport.y/viewport.z,"long dialogue panel stays inside scaled viewport "+viewport);
    Near(panel.height,viewport.y/viewport.z-40,"long dialogue leaves vertical screen margins");
    Rect shortPanel=PassengerDialogueUI.PanelBounds(viewport.x,viewport.y,viewport.z,240);Near(shortPanel.height,240,"short dialogue retains natural height");
    Check(panel.width<=600&&panel.width<=viewport.x/viewport.z-40,"dialogue width fits scaled viewport");
   }
   Check(PassengerRequestChoices.SatisfactionEffect(RequestKind.Empathy,PassengerReply.Accept).Contains("즉시 만족도 +3점"),"request description uses independent immediate value");
   Check(PassengerRequestChoices.SatisfactionEffect(RequestKind.Empathy,PassengerReply.Accept).Contains("운행 중 만족도 +6점/분"),"request description exposes per-minute unit");
   var foodDescription=new PassengerBehaviorState{Type=PassengerType.Food};Check(foodDescription.ChoiceEffects[1].Contains("즉시 만족도 +9점")&&foodDescription.ChoiceEffects[1].Contains("청결도")&&!foodDescription.ChoiceEffects[1].Contains("만족도 +5"),"food describes configured effect and keeps dirt behavior");
   var sleepDescription=new PassengerBehaviorState{Type=PassengerType.Sleeping,FollowupPending=true};Check(sleepDescription.ChoiceEffects[0].Contains("즉시 만족도 +4점"),"sleep followup describes distinct choice ID");
   var situationDescription=new PassengerSituationState{Pending=PassengerSituationKind.Jolt,LuggageLoaded=true,Type=PassengerType.Luggage};Check(situationDescription.ReplyEffect(0).Contains("즉시 피로 -2점")&&situationDescription.ReplyEffect(0).Contains("재고정"),"situation description keeps physical resecure and edited fatigue");
   root=new GameObject("choice effects scene-free checks");var session=root.AddComponent<DriveSession>();var business=root.AddComponent<BusinessProgress>();var jobs=root.AddComponent<PassengerJobs>();var law=root.AddComponent<DrivingLaw>();var manners=root.AddComponent<DrivingManners>();
   session.business=business;session.jobs=jobs;session.law=law;session.manners=manners;business.session=session;business.useV2=true;business.settings=PrototypeSettings.ForOneDay();business.ledger=new EconomyLedger(business.settings);jobs.session=session;law.session=session;manners.session=session;
   law.tripId="choice-test-trip";jobs.current=new JobOffer{candidateSeed="choice-test-seed",requiredScore=70};Check(jobs.trip.Accept(1000,600,60)&&jobs.trip.Board(),"fixture boarded");
   typeof(PassengerJobs).GetProperty("StartSatisfaction",BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).SetValue(jobs,70,null);
   jobs.BeginChoiceEffectsForTrip();Check(jobs.ChoiceEffectsActive,"schema2 starts ledger");double f=business.ledger.Driver.fatigue;
   string empathy="choice-test-trip:request:Empathy";jobs.SelectChoiceEffect(empathy,"request.Empathy.Accept");Near(jobs.ChoiceEffects.SatisfactionDelta,3,"immediate satisfaction");Near(jobs.ScoreView.value,73,"immediate contributes to actual score view");Near(business.ledger.Driver.fatigue,f+2,"immediate driver fatigue");Near(business.ledger.Driver.choiceFatigueGrowthPercent,100,"natural growth modifier");
   jobs.SelectChoiceEffect(empathy,"request.Empathy.Accept");Near(jobs.ChoiceEffects.SatisfactionDelta,3,"repeat selection no satisfaction");Near(business.ledger.Driver.fatigue,f+2,"repeat selection no fatigue");
   jobs.SelectChoiceEffect("choice-test-trip:request:RouteAdvice","request.RouteAdvice.Alternative");Near(jobs.ChoiceEffects.SatisfactionDelta,3,"independent alternative remains zero");
   Clock(business.ledger,60);jobs.TickChoiceEffects();Near(jobs.ChoiceEffects.SatisfactionDelta,9,"one minute additional satisfaction");Near(business.ledger.Driver.fatigue,f+3,"one minute additional fatigue");jobs.TickChoiceEffects();Near(jobs.ChoiceEffects.SatisfactionDelta,9,"same business time no duplicate tick");
   session.paused=true;Clock(business.ledger,120);jobs.TickChoiceEffects();Near(jobs.ChoiceEffects.SatisfactionDelta,9,"pause excludes business interval");session.paused=false;jobs.TickChoiceEffects();Near(jobs.ChoiceEffects.SatisfactionDelta,9,"resume does not catch up paused interval");Clock(business.ledger,180);jobs.TickChoiceEffects();Near(jobs.ChoiceEffects.SatisfactionDelta,15,"resume advances new interval");
   var snapshot=new PassengerJobsSnapshot{trip=jobs.trip.Snapshot(),current=jobs.current};jobs.CaptureChoiceEffects(snapshot);PassengerJobs.ValidateChoiceEffectsSnapshot(snapshot);var json=JsonUtility.ToJson(snapshot);var restored=JsonUtility.FromJson<PassengerJobsSnapshot>(json);PassengerJobs.ValidateChoiceEffectsSnapshot(restored);var wrongEvent=new PassengerJobsSnapshot{trip=snapshot.trip,current=snapshot.current,choiceEffectsVersion=1,choiceEffectsPresent=true,choiceEffects=snapshot.choiceEffects.Copy(),choiceEffectsTrip=snapshot.choiceEffectsTrip,choiceEffectsOwner=snapshot.choiceEffectsOwner,choiceEffectsElapsed=snapshot.choiceEffectsElapsed};
   wrongEvent.choiceEffects.entries[0].eventId="choice-test-trip:request:Quiet";Reject(()=>PassengerJobs.ValidateChoiceEffectsSnapshot(wrongEvent),"known request choice cannot use another kind event");
   wrongEvent.choiceEffects=snapshot.choiceEffects.Copy();wrongEvent.request=new PassengerRequestUISnapshot{version=2,observations=new[]{new PassengerRequestObservationSnapshot{request=new PassengerRequestSnapshot{kind=RequestKind.Empathy,replyCaptured=true,reply=PassengerReply.Alternative}},new PassengerRequestObservationSnapshot{request=new PassengerRequestSnapshot{kind=RequestKind.RouteAdvice,replyCaptured=true,reply=PassengerReply.Alternative}}}};Reject(()=>PassengerJobs.ValidateChoiceEffectsSnapshot(wrongEvent),"choice must match saved actual request reply");
   wrongEvent.request.observations[0].request.reply=PassengerReply.Accept;PassengerJobs.ValidateChoiceEffectsSnapshot(wrongEvent);Check(true,"matching request observations accepted");wrongEvent.request=null;wrongEvent.choiceEffectsLegacyTransport=true;Reject(()=>PassengerJobs.ValidateChoiceEffectsSnapshot(wrongEvent),"legacy marker cannot coexist with ledger");wrongEvent.choiceEffectsLegacyTransport=false;
   wrongEvent.choiceEffects=new ChoiceEffectLedger();wrongEvent.choiceEffects.Select("choice-test-trip:type:Drunk:initial","type.Food.1",70,20);Reject(()=>PassengerJobs.ValidateChoiceEffectsSnapshot(wrongEvent),"known type choice cannot use another type event");
   wrongEvent.choiceEffects=new ChoiceEffectLedger();wrongEvent.choiceEffects.Select("choice-test-trip:type:Sleeping:initial","type.SleepingFollowup.0",70,20);Reject(()=>PassengerJobs.ValidateChoiceEffectsSnapshot(wrongEvent),"followup cannot use initial type event");
   wrongEvent.choiceEffects=new ChoiceEffectLedger();wrongEvent.choiceEffects.Select("choice-test-trip:situation:999","situation.Jolt.0",70,20);Reject(()=>PassengerJobs.ValidateChoiceEffectsSnapshot(wrongEvent),"situation event number must be reachable");
   wrongEvent.choiceEffects=new ChoiceEffectLedger();wrongEvent.choiceEffects.Select("choice-test-trip:situation:0","situation.Jolt.0",70,20);PassengerJobs.ValidateChoiceEffectsSnapshot(wrongEvent);Check(true,"scene-free situation fixture and null request supported");
   var oldLedger=jobs.ChoiceEffects;double before=business.ledger.Driver.fatigue;jobs.RestoreChoiceEffects(restored);Check(!ReferenceEquals(oldLedger,jobs.ChoiceEffects),"restore makes independent ledger");jobs.SelectChoiceEffect(empathy,"request.Empathy.Accept");Near(jobs.ChoiceEffects.SatisfactionDelta,15,"JSON restore no immediate replay");Near(business.ledger.Driver.fatigue,before,"JSON restore no fatigue replay");
   Near(jobs.CompleteChoiceRequest(RequestKind.Empathy,PassengerReply.Accept,1),7,"actual successful request contribution");Near(jobs.ChoiceEffects.RequestEndFor(empathy),7,"request contribution separated");Near(jobs.ChoiceEffects.SatisfactionDelta,15,"request end excluded from immediate ledger score");Near(business.ledger.Driver.fatigue,before+3,"request end driver fatigue");Near(jobs.CompleteChoiceRequest(RequestKind.Empathy,PassengerReply.Accept,1),7,"request end repeat returns recorded contribution");Near(business.ledger.Driver.fatigue,before+3,"request end repeat no fatigue");
   string defer="choice-test-trip:request:Quiet";jobs.SelectChoiceEffect(defer,"request.Quiet.Defer");Near(jobs.CompleteChoiceRequest(RequestKind.Quiet,PassengerReply.Defer,0),0,"defer uses neutral zero end");
   jobs.CancelChoiceEffects();Near(business.ledger.Driver.choiceFatigueGrowthPercent,0,"cancel clears natural growth modifier");before=business.ledger.Driver.fatigue;int s=jobs.ChoiceEffects.SatisfactionDelta;Clock(business.ledger,240);jobs.TickChoiceEffects();Near(jobs.ChoiceEffects.SatisfactionDelta,s,"cancel freezes satisfaction");Near(business.ledger.Driver.fatigue,before,"cancel freezes additional fatigue");
   jobs.RestoreChoiceEffects(new PassengerJobsSnapshot{trip=jobs.trip.Snapshot()});Check(!jobs.ChoiceEffectsActive,"old snapshot preserves legacy transport");Near(business.ledger.Driver.choiceFatigueGrowthPercent,0,"old snapshot no modifier");
   jobs.trip.Clear();Check(jobs.trip.Accept(1000,600,60),"legacy pickup fixture accepted");var freshPickup=new PassengerJobsSnapshot{choiceEffectsVersion=1,current=jobs.current,trip=jobs.trip.Snapshot()};PassengerJobs.ValidateChoiceEffectsSnapshot(freshPickup);Check(true,"new pickup can persist before first choice ledger");jobs.RestoreChoiceEffects(new PassengerJobsSnapshot{current=jobs.current,trip=jobs.trip.Snapshot()});Check(jobs.trip.Board(),"legacy pickup becomes boarded");jobs.BeginChoiceEffectsForTrip();Check(!jobs.ChoiceEffectsActive,"old pickup cannot enable effects at boarding");jobs.CancelChoiceEffects();jobs.BeginChoiceEffectsForTrip();Check(jobs.ChoiceEffectsActive,"new transport boundary resets legacy sentinel");jobs.CancelChoiceEffects();
   var fractional=ContentJson.Object(ContentJson.Parse(ContentTuning.CaptureJson()));Set(fractional,"choice.type.Food.1.immediate.satisfaction",0);Set(fractional,"choice.type.Food.1.immediate.satisfactionPercent",10);fractional["contentHash"]=ContentTuning.ComputeHash(fractional);ContentTuning.UseJson(ContentJson.Stringify(fractional));jobs.BeginChoiceEffectsForTrip();jobs.SelectChoiceEffect(empathy,"request.Empathy.Accept");Clock(business.ledger,241);jobs.TickChoiceEffects();Near(jobs.ChoiceEffects.satisfactionContribution,3.1,"fractional one-second rate retained");jobs.SelectChoiceEffect("choice-test-trip:type:Food:initial","type.Food.1");Near(jobs.ChoiceEffects.satisfactionContribution,10.41,"next percent uses exact current satisfaction before display rounding");
   var legacyObservation=new PassengerJobsSnapshot{choiceEffectsVersion=1,choiceEffectsPresent=true,choiceEffectsTrip=law.tripId,choiceEffectsOwner=jobs.current.candidateSeed,current=jobs.current,trip=jobs.trip.Snapshot(),choiceEffects=new ChoiceEffectLedger(),request=new PassengerRequestUISnapshot{version=0,observations=new PassengerRequestObservationSnapshot[0],request=new PassengerRequestSnapshot{trip=law.tripId,kind=RequestKind.Empathy,replyCaptured=true,reply=PassengerReply.Accept}}};legacyObservation.choiceEffects.Select(law.tripId+":request:Empathy","request.Empathy.Accept",70,20);PassengerJobs.ValidateChoiceEffectsSnapshot(legacyObservation);Check(true,"legacy observation uses its captured reply when JSON produces empty observations array");
   var absentJson=JsonUtility.FromJson<PassengerJobsSnapshot>(JsonUtility.ToJson(new PassengerJobsSnapshot{choiceEffectsVersion=1}));PassengerJobs.ValidateChoiceEffectsSnapshot(absentJson);Check(absentJson.choiceEffects==null,"JSON absence marker tolerates generated empty nested object");
   var hidden=new PassengerJobsSnapshot{choiceEffectsVersion=1,choiceEffects=new ChoiceEffectLedger{ satisfactionContribution=1 }};Reject(()=>PassengerJobs.ValidateChoiceEffectsSnapshot(hidden),"absence marker rejects hidden applied effects");
   var failureProfile=ContentJson.Object(ContentJson.Parse(ContentTuning.CaptureJson()));Set(failureProfile,"choice.request.Comfort.Accept.end.failure.satisfaction",-7);Set(failureProfile,"choice.request.Comfort.Accept.end.failure.fatigue",-2);failureProfile["contentHash"]=ContentTuning.ComputeHash(failureProfile);ContentTuning.UseJson(ContentJson.Stringify(failureProfile));jobs.CancelChoiceEffects();jobs.BeginChoiceEffectsForTrip();var comfort=root.AddComponent<PassengerRequestObservation>();comfort.enabled=false;comfort.session=session;comfort.BeginKind(RequestKind.Comfort);comfort.request.Accept();jobs.RecordRequestChoice(RequestKind.Comfort,PassengerReply.Accept);before=business.ledger.Driver.fatigue;manners.brakeEvents++;comfort.Finish();Check(comfort.request.GoalOutcome==-1&&comfort.request.SatisfactionDelta==-7,"actual harsh observation chooses independent failure end");Near(business.ledger.Driver.fatigue,before-2,"actual failure end applies configured driver fatigue");
   Debug.Log("CHOICE_EFFECTS_RUNTIME_CHECKS_OK checks="+checks);
  }finally{Time.timeScale=originalScale;ContentTuning.UseJson(original);if(root)UnityEngine.Object.DestroyImmediate(root);}
 }
}
